const records=[];
for(const filename of ['entity-extraction-v10-diagnostic.json','entity-extraction-v11-boundary-diagnostic.json']){
 const sourceText=text(join(repo,'docs/public',filename)),source=JSON.parse(sourceText);
 for(const capture of source.captures.flatMap(value=>value.records)){
  assert.equal(capture.result.captureStatus,'output');
  const sample=corpus.cases.find(value=>value.caseId===capture.caseId),input=entityReviewInput(sample);
  assert.equal(capture.inputDigest,digest(JSON.stringify(input)));
  const checked=reviewCapturedOutput(sample,capture.result.output,value=>checkWindowExtractionResponse(value,input.excerpts));
  const original=source.records.find(value=>value.caseId===capture.caseId);
  assert.ok(original.checked,'Original admission is required for byte-independent replay check.');
  assert.deepEqual(checked.checked,original.checked);
  records.push({sourceEvidence:filename,sourceEvidenceDigest:digest(sourceText),sourceMeasurementId:source.manifest.measurementId,sourcePromptVersion:source.manifest.promptVersion,caseId:capture.caseId,inputDigest:capture.inputDigest,outputDigest:digest(capture.result.output),originalOutput:capture.result.output,originalOutcome:original,replayedOutcome:checked,admissionUnchanged:true});
 }
}
