assert.ok(actual.replayedOutcome.checks.criticalMentions.every(value=>value.status==='matched'));
assert.equal(actual.originalOutcome.checks.criticalMentionRecall.matched,2);
const old=records.find(value=>value.sourcePromptVersion==='knowledge-extraction-v10'&&value.caseId==='held-code-state-without-sha');
assert.equal(old.replayedOutcome.checks.criticalMentions.find(value=>value.mentionKey==='state-unreleased').status,'missing');
